func TestCustomersListDryRunAgentSuppressesHumanPreview(t *testing.T) {
	configPath := writeDryRunTestConfig(t)

	cmd := RootCmd()
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	cmd.SetArgs([]string{"customers", "list", "--dry-run", "--agent", "--config", configPath})

	processStderr, err := captureProcessStderr(t, func() error {
		return cmd.Execute()
	})
	if err != nil {
		t.Fatalf("customers list --dry-run --agent returned error: %v", err)
	}
	if stderr.Len() != 0 {
		t.Fatalf("customers list --dry-run --agent wrote command stderr: %q", stderr.String())
	}
	if processStderr != "" {
		t.Fatalf("customers list --dry-run --agent wrote human preview to process stderr: %q", processStderr)
	}
	if strings.Contains(stdout.String(), "GET ") || strings.Contains(stdout.String(), "dry run - no request sent") {
		t.Fatalf("stdout should contain only JSON agent output, got %q", stdout.String())
	}

	var got struct {
		SchemaVersion string `json:"schema_version"`
		Data          struct {
			DryRun bool `json:"dry_run"`
		} `json:"data"`
		Error any `json:"error"`
	}
	if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
		t.Fatalf("customers list --dry-run --agent emitted invalid JSON: %v\n%s", err, stdout.String())
	}
	if got.SchemaVersion != "1.0" {
		t.Fatalf("schema_version: want 1.0, got %q", got.SchemaVersion)
	}
	if !got.Data.DryRun {
		t.Fatalf("agent data should report dry_run true: %#v", got.Data)
	}
	if got.Error != nil {
		t.Fatalf("agent error should be null: %#v", got.Error)
	}
}

func TestCustomersListDryRunWithoutAgentKeepsHumanPreview(t *testing.T) {
	configPath := writeDryRunTestConfig(t)

	cmd := RootCmd()
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	cmd.SetArgs([]string{"customers", "list", "--dry-run", "--config", configPath})

	processStderr, err := captureProcessStderr(t, func() error {
		return cmd.Execute()
	})
	if err != nil {
		t.Fatalf("customers list --dry-run returned error: %v", err)
	}
	if stderr.Len() != 0 {
		t.Fatalf("customers list --dry-run wrote command stderr: %q", stderr.String())
	}
	if !strings.Contains(processStderr, "GET https://sandbox.straddle.com/v1/customers") {
		t.Fatalf("non-agent dry-run should keep request preview, got %q", processStderr)
	}
	if !strings.Contains(processStderr, "(dry run - no request sent)") {
		t.Fatalf("non-agent dry-run should keep no-request notice, got %q", processStderr)
	}
	if stdout.Len() == 0 {
		t.Fatalf("dry-run should still emit command result data")
	}
}

func TestPrintProvenanceSuppressesAgentModeWhenTerminal(t *testing.T) {
	restore := forceTerminalForDryRunTest(t)
	defer restore()

	cmd := RootCmd()
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	if err := cmd.PersistentFlags().Set("agent", "true"); err != nil {
		t.Fatalf("setting agent flag: %v", err)
	}

	printProvenance(cmd, 3, DataProvenance{Source: "live"})

	if stderr.Len() != 0 {
		t.Fatalf("agent provenance should be suppressed, got %q", stderr.String())
	}
}

