func writeDryRunTestConfig(t *testing.T) string {
	t.Helper()

	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("STRADDLE_CONFIG", "")
	t.Setenv("STRADDLE_BASE_URL", "")
	t.Setenv("STRADDLE_TOKEN", "")

	configPath := filepath.Join(home, ".config", "straddle-pp-cli", "config.toml")
	if err := os.MkdirAll(filepath.Dir(configPath), 0o700); err != nil {
		t.Fatalf("creating config dir: %v", err)
	}
	if err := os.WriteFile(configPath, []byte("base_url = \"https://sandbox.straddle.com\"\n"), 0o600); err != nil {
		t.Fatalf("writing config: %v", err)
	}
	return configPath
}

func forceTerminalForDryRunTest(t *testing.T) func() {
	t.Helper()

	old := isTerminalWriter
	isTerminalWriter = func(io.Writer) bool {
		return true
	}
	return func() {
		isTerminalWriter = old
	}
}

func captureProcessStderr(t *testing.T, fn func() error) (string, error) {
	t.Helper()

	oldStderr := os.Stderr
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("creating stderr pipe: %v", err)
	}
	os.Stderr = w
	defer func() {
		os.Stderr = oldStderr
	}()

	callErr := fn()
	if err := w.Close(); err != nil {
		t.Fatalf("closing stderr pipe: %v", err)
	}
	out, readErr := io.ReadAll(r)
	if closeErr := r.Close(); closeErr != nil {
		t.Fatalf("closing stderr reader: %v", closeErr)
	}
	if readErr != nil {
		t.Fatalf("reading stderr pipe: %v", readErr)
	}
	return string(out), callErr
}
